    std::time_t now = std::time(nullptr);
    std::tm* now_tm = std::localtime(&now);

    char buffer[20];
    std::strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", now_tm);

    return "[" + std::string(buffer) + "] Received: " + msg;
}
